list_trash.code:
const response = await client.trash.listTrash({type: 'Category', search: 'spring', sort: 'name', order: 'asc', limit: 20});
for (const item of response.map.items) {
    console.log(item.id, item.type, item.name, item.removed_at);
}
console.log(response.map.pagination.total, response.map.pagination.has_next);

list_trash_types.code:
const response = await client.trash.listTrashTypes();
for (const entry of response.map.types) {
    console.log(entry.type);
}

restore_trash_item.code:
const response = await client.trash.restoreTrashItem('Category', 1234);
const item = response.map.item;
console.log(item.type, item.id, item.name, item.url);

bulk_restore_trash.code:
const response = await client.trash.bulkRestoreTrash({
    items: [{type: 'Category', id: 1234}, {type: 'BlogPost', id: 99}],
});
for (const item of response.map.restored) {
    console.log(item.type, item.id, item.name, item.url);
}
for (const failure of response.map.failed) {
    console.log(failure.type, failure.id, failure.code, failure.message);
}

bulk_delete_trash.code:
